17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.web.bind.annotation.CrossOrigin;
48	import org.springframework.web.bind.annotation.RequestMapping;
49	import org.springframework.web.bind.annotation.RestController;
50	import org.springframework.web.util.UriComponentsBuilder;
51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
65	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
66	     * stored lower-cased.
67	     */
68	    private static final Pattern EMAIL_PATTERN =
69	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        validateRequiredOwnerFields(ownerFieldsDto);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
121	        owner.setTelephone(normalizedTelephone);
122	        rejectDuplicateTelephone(normalizedTelephone);
123	        owner.setEmail(normalizeEmail(owner.getEmail()));
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
128	        this.clinicService.saveOwner(owner);
129	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
130	        headers.setLocation(UriComponentsBuilder.newInstance()
131	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
132	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
138	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
139	        if (currentOwner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        currentOwner.setAddress(ownerFieldsDto.getAddress());
143	        currentOwner.setCity(ownerFieldsDto.getCity());
144	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
145	        currentOwner.setLastName(ownerFieldsDto.getLastName());
146	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
147	        this.clinicService.saveOwner(currentOwner);
148	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
149	    }
150	
151	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
152	    @Transactional
153	    @Override
154	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
155	        Owner owner = this.clinicService.findOwnerById(ownerId);
156	        if (owner == null) {
157	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
158	        }
159	        this.clinicService.deleteOwner(owner);
160	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
166	        Owner owner = this.clinicService.findOwnerById(ownerId);
167	        if (owner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        HttpHeaders headers = new HttpHeaders();
171	        Pet pet = petMapper.toPet(petFieldsDto);
172	        owner.setId(ownerId);
173	        pet.setOwner(owner);
174	        pet.getType().setName(null);
175	        this.clinicService.savePet(pet);
176	        PetDto petDto = petMapper.toPetDto(pet);
177	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
178	            .buildAndExpand(pet.getId()).toUri());
179	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
185	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
186	        if (currentOwner != null) {
187	            Pet currentPet = this.clinicService.findPetById(petId);
188	            if (currentPet != null) {
189	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
190	                currentPet.setName(petFieldsDto.getName());
191	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
192	                this.clinicService.savePet(currentPet);
193	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
194	            }
195	        }
196	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
202	        HttpHeaders headers = new HttpHeaders();
203	        Visit visit = visitMapper.toVisit(visitFieldsDto);
204	        Pet pet = new Pet();
205	        pet.setId(petId);
206	        visit.setPet(pet);
207	        this.clinicService.saveVisit(visit);
208	        VisitDto visitDto = visitMapper.toVisitDto(visit);
209	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
210	            .buildAndExpand(visit.getId()).toUri());
211	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
212	    }
213	
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner != null) {
220	            Pet pet = owner.getPet(petId);
221	            if (pet != null) {
222	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
223	            }
224	        }
225	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	    }
227	
228	    /**
229	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
230	     * offending field is collected so the caller learns exactly which values must be supplied.
231	     *
232	     * @param ownerFieldsDto the submitted owner payload
233	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
234	     *         telephone is missing or blank
235	     */
236	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
237	        List<String> missingFields = new ArrayList<>();
238	        if (isBlank(ownerFieldsDto.getFirstName())) {
239	            missingFields.add("firstName");
240	        }
241	        if (isBlank(ownerFieldsDto.getLastName())) {
242	            missingFields.add("lastName");
243	        }
244	        if (isBlank(ownerFieldsDto.getAddress())) {
245	            missingFields.add("address");
246	        }
247	        if (isBlank(ownerFieldsDto.getCity())) {
248	            missingFields.add("city");
249	        }
250	        if (isBlank(ownerFieldsDto.getTelephone())) {
251	            missingFields.add("telephone");
252	        }
253	        if (!missingFields.isEmpty()) {
254	            throw new MissingOwnerFieldsException(missingFields);
255	        }
256	    }
257	
258	    private boolean isBlank(String value) {
259	        return value == null || value.isBlank();
260	    }
261	
262	    /**
263	     * Builds an owner's customer code, formatted '&lt;LAST3&gt;-&lt;NNNN&gt;'. LAST3 is the
264	     * upper-cased first three letters of the last name; NNNN is a global 4-digit zero-padded
265	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
266	     *
267	     * @param lastName the owner's last name
268	     * @return the formatted customer code
269	     */
270	    private String generateCustomerCode(String lastName) {
271	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
272	        int sequence = this.clinicService.findAllOwners().size() + 1;
273	        return String.format("%s-%04d", last3, sequence);
274	    }
275	
276	    /**
277	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
278	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
279	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
280	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
281	     * stored and returned.
282	     *
283	     * @param telephone the raw telephone value from the request
284	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
285	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
286	     */
287	    private String normalizeTelephone(String telephone) {
288	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
289	        String e164;
290	        if (cleaned.startsWith("+")) {
291	            e164 = cleaned;
292	        } else {
293	            String national = cleaned;
294	            if (national.startsWith("0")) {
295	                national = national.substring(1);
296	            }
297	            e164 = "+61" + national;
298	        }
299	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
300	            throw new InvalidOwnerFieldsException(List.of("telephone"));
301	        }
302	        return e164;
303	    }
304	
305	    /**
306	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
307	     * left unset. When a value is present it must be a syntactically valid address; the normalized
308	     * form stored and returned is the value lower-cased.
309	     *
310	     * @param email the raw email value from the request, or {@code null} when none was supplied
311	     * @return the lower-cased email, or {@code null} when no email was supplied
312	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
313	     */
314	    private String normalizeEmail(String email) {
315	        if (email == null || email.isBlank()) {
316	            return null;
317	        }
318	        if (!EMAIL_PATTERN.matcher(email).matches()) {
319	            throw new InvalidOwnerFieldsException(List.of("email"));
320	        }
321	        return email.toLowerCase(Locale.ROOT);
322	    }
323	
324	    /**
325	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
326	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
327	     * directly and is therefore independent of the punctuation a caller supplied.
328	     *
329	     * @param e164Telephone the E.164 telephone of the owner being created
330	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
331	     */
332	    private void rejectDuplicateTelephone(String e164Telephone) {
333	        boolean inUse = this.clinicService.findAllOwners().stream()
334	            .map(Owner::getTelephone)
335	            .filter(existing -> existing != null)
336	            .anyMatch(e164Telephone::equals);
